'use client';

import React from 'react';
import { cn, type DeviceStatus, type LinkMode } from './topology-types.js';

export interface CableBadgeProps {
  mode?: LinkMode;
  speed?: string;
  status?: DeviceStatus;
  animated?: boolean;
  label?: string;
  /** 'badge' (standalone pill), 'wire' (stretched cable line with center chip), or 'pill' (compact) */
  variant?: 'badge' | 'wire' | 'pill';
  className?: string;
}

export const MODE_LABEL: Record<LinkMode, string> = {
  trunk: 'Trunk (802.1Q)',
  access: 'Access Port',
  routed: 'Routed L3',
  tunnel: 'Overlay Tunnel',
  peering: 'eBGP Peering',
  stack: 'StackWise Backplane',
};

export const CABLE_STATUS_COLOR: Record<DeviceStatus, string> = {
  up: 'bg-emerald-500 border-emerald-500 text-emerald-500',
  degraded: 'bg-amber-500 border-amber-500 text-amber-500',
  down: 'bg-rose-500 border-rose-500 text-rose-500',
  planned: 'bg-sky-500 border-sky-500 text-sky-500',
  unknown: 'bg-slate-400 border-slate-400 text-slate-400',
};

export function CableBadge({
  mode = 'trunk',
  speed = '10G',
  status = 'up',
  animated = false,
  label,
  variant = 'badge',
  className,
}: CableBadgeProps) {
  // Wire mode: stretches horizontally between devices with extending lines and a center speed pill
  if (variant === 'wire') {
    return (
      <div className={cn('relative flex items-center justify-center w-full my-0.5', className)}>
        {/* Full-width cable wire */}
        <div
          className={cn(
            'w-full transition-all',
            mode === 'trunk' && 'border-y border-emerald-500 h-2 bg-emerald-500/10',
            mode === 'tunnel' && 'border-b-2 border-dashed border-sky-500 h-0',
            mode === 'peering' && 'border-b-2 border-dotted border-purple-500 h-0',
            mode === 'stack' && 'h-1.5 rounded-full bg-indigo-500',
            mode !== 'trunk' &&
              mode !== 'tunnel' &&
              mode !== 'peering' &&
              mode !== 'stack' &&
              cn('h-1 rounded-full', CABLE_STATUS_COLOR[status]?.split(' ')[0]),
          )}
        />

        {/* Center badge chip */}
        <div className="absolute flex items-center gap-1.5 px-2 py-0.5 rounded-full border border-border bg-background shadow-xs text-[10.5px] font-mono font-bold tracking-tight">
          {animated && (
            <span
              className={cn(
                'size-1.5 rounded-full animate-ping',
                status === 'up' ? 'bg-emerald-400' : 'bg-amber-400',
              )}
            />
          )}
          <span className="text-foreground">{label || speed}</span>
          {mode === 'trunk' && (
            <span className="text-[9px] font-sans font-medium text-muted-foreground uppercase">
              Trunk
            </span>
          )}
          {mode === 'tunnel' && (
            <span className="text-[9px] font-sans font-medium text-sky-500 uppercase">
              Tunnel
            </span>
          )}
        </div>
      </div>
    );
  }

  // Pill mode: ultra-compact cable connection for inline text
  if (variant === 'pill') {
    return (
      <span className={cn('relative inline-flex items-center justify-center px-1 shrink-0', className)}>
        <span
          className={cn(
            'w-8 transition-all',
            mode === 'trunk' && 'border-y border-emerald-500 h-1.5 bg-transparent',
            mode === 'tunnel' && 'border-b-2 border-dashed border-sky-500 h-0',
            mode === 'peering' && 'border-b-2 border-dotted border-purple-500 h-0',
            mode !== 'trunk' &&
              mode !== 'tunnel' &&
              mode !== 'peering' &&
              cn('h-0.5 rounded-full', CABLE_STATUS_COLOR[status]?.split(' ')[0]),
          )}
        />
        {speed && (
          <span className="absolute -top-3.5 text-[9px] font-mono font-bold tracking-tight text-muted-foreground">
            {speed}
          </span>
        )}
        {animated && (
          <span className="absolute size-1.5 rounded-full bg-emerald-400 animate-ping" />
        )}
      </span>
    );
  }

  // Default: standalone badge
  return (
    <div
      className={cn(
        'inline-flex items-center gap-2 px-2.5 py-1 rounded-xl border border-border bg-card text-xs shadow-xs font-sans select-none',
        className,
      )}
    >
      {/* Cable line preview */}
      <div className="relative flex items-center w-6 h-2 shrink-0">
        <span
          className={cn(
            'w-full h-0.5 rounded-full',
            mode === 'trunk' && 'border-y border-emerald-500 h-1.5 bg-transparent',
            mode === 'tunnel' && 'border-b border-dashed border-sky-500 h-0',
            mode === 'peering' && 'border-b border-dotted border-purple-500 h-0',
            mode !== 'trunk' &&
              mode !== 'tunnel' &&
              mode !== 'peering' &&
              cn('h-0.5 rounded-full', CABLE_STATUS_COLOR[status]?.split(' ')[0]),
          )}
        />
        {animated && (
          <span className="absolute inset-0 animate-ping opacity-75 rounded-full bg-emerald-400" />
        )}
      </div>

      <span className="font-medium text-foreground">
        {label || MODE_LABEL[mode] || mode}
      </span>

      {speed && (
        <span className="font-mono text-[10px] px-1.5 py-0.5 rounded bg-primary/10 text-primary font-semibold">
          {speed}
        </span>
      )}
    </div>
  );
}

// Shared helpers for the Marrow UI components. The registry build
// (scripts/build-registry.mjs) ships this file verbatim as
// `topology-types.ts`, so it must stay self-contained: it may import only
// clsx and tailwind-merge, which every registry item declares.
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/** shadcn's `cn`: conditional classes, with later Tailwind classes winning (`p-2 p-4` → `p-4`). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Mirrors DEVICE_STATUSES / LINK_MODES in @marrow/model. Declared as literals
// because copied registry files cannot import @marrow/*; packages/ui/test
// asserts they stay equal to the model's.
export const DEVICE_STATUSES = ['up', 'down', 'degraded', 'planned', 'unknown'] as const;
export type DeviceStatus = (typeof DEVICE_STATUSES)[number];

export const LINK_MODES = ['access', 'trunk', 'routed', 'tunnel', 'peering', 'stack'] as const;
export type LinkMode = (typeof LINK_MODES)[number];

// Mirrors EMBED / EMBED_HASH in @marrow/runtime's page contract — the
// postMessage names a host and an embedded diagram exchange, and the hash
// that switches a diagram to embed chrome. Literals for the same reason as
// above; packages/ui/test/embed-parity.test.ts asserts they stay equal.
export const MARROW_EMBED = {
  theme: 'marrow:theme',
  ready: 'marrow:ready',
  hash: '#embed=true',
} as const;

// Mirrors ROOT_ATTR in @marrow/runtime's page contract — the <html>
// attributes the pre-boot script and stylesheet key off. MarrowEmbed writes
// them into `html` (srcdoc) markup, which has no URL to carry flags in.
// Same parity test as MARROW_EMBED.
export const MARROW_ROOT_ATTR = {
  theme: 'data-theme',
  themeMode: 'data-theme-mode',
  chrome: 'data-chrome',
  inspector: 'data-inspector',
  minimap: 'data-minimap',
} as const;

